window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"2ecNN-Z4EJA","speaker":"Alix Didier Fils-Aimé","role":"Prime Minister","country":"Haiti","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=2ecNN-Z4EJA","date":"20260925","title":"🇭🇹 Haiti -  Prime Minister Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1469,"words":3057,"counts":{"claims":40,"promises":8,"attacks":0},"topics":[{"topic":"Haiti security","share":0.1687,"seconds":248},{"topic":"Haiti elections","share":0.1382,"seconds":203},{"topic":"Haiti migration","share":0.0924,"seconds":136},{"topic":"Haiti crisis","share":0.0823,"seconds":121},{"topic":"Climate finance","share":0.0455,"seconds":67},{"topic":"Haiti violence","share":0.0452,"seconds":66},{"topic":"Haiti climate","share":0.0449,"seconds":66},{"topic":"Haiti aid","share":0.0446,"seconds":65},{"topic":"UNGA","share":0.0441,"seconds":65},{"topic":"Haiti France relations","share":0.0431,"seconds":63},{"topic":"Haiti history","share":0.0428,"seconds":63},{"topic":"Haiti justice","share":0.0422,"seconds":62},{"topic":"Haiti development","share":0.0418,"seconds":61},{"topic":"Haiti liberty","share":0.0418,"seconds":61},{"topic":"Haiti trade","share":0.0413,"seconds":61},{"topic":"Haiti disarmament","share":0.0413,"seconds":61}],"timeline":[[2,66,null],[68,128,"Haiti crisis"],[129,194,"UNGA"],[195,255,"Haiti security"],[256,319,"Haiti history"],[319,381,"Haiti liberty"],[382,448,"Haiti climate"],[450,517,"Climate finance"],[518,587,"Haiti migration"],[588,655,"Haiti migration"],[656,716,"Haiti crisis"],[718,785,"Haiti violence"],[786,846,"Haiti security"],[847,913,"Haiti security"],[919,980,"Haiti security"],[981,1043,"Haiti justice"],[1044,1105,"Haiti disarmament"],[1106,1166,"Haiti trade"],[1168,1233,"Haiti aid"],[1234,1315,"Haiti elections"],[1316,1377,"Haiti elections"],[1379,1439,"Haiti elections"],[1444,1508,"Haiti France relations"],[1509,1570,"Haiti development"],[1570,1587,null]],"stances":{"Haiti crisis":"Alix Didier Fils-Aimé states that Haiti is facing a severe crisis and calls for global unity to address peace, security, and human well-being.","UNGA":"Alix Didier Fils-Aimé congratulates the new president of the General Assembly and expresses gratitude to international partners for their support.","Haiti security":"Alix Didier Fils-Aimé expresses gratitude for the contributions of international partners to Haiti's gang suppression efforts and national security modernization.","Haiti history":"Alix Didier Fils-Aimé emphasizes Haiti's historical role as the first free black republic and its enduring struggle for freedom.","Haiti liberty":"Alix Didier Fils-Aimé states that Haiti will resist criminal violence threatening the nation's freedom.","Haiti climate":"Alix Didier Fils-Aimé states that Haiti is resilient despite chaos and argues that the world should support rather than save the nation, while highlighting the disproportionate burden of climate change on small states.","Climate finance":"Alix Didier Fils-Aimé argues that the international financial system must evolve to ensure fair access to capital and technology for vulnerable countries, while emphasizing that people should not have to choose between emergency response and development.","Haiti migration":"Alix Didier Fils-Aimé emphasizes the need for dignity in migration policies and expresses a commitment to restoring Haiti as a land of welcome, refuge, and hope where citizens can return and build their futures.","Haiti violence":"Alix Didier Fils-Aimé calls for immediate and full action against the violence in Haiti while honoring the victims and fallen security personnel.","Haiti justice":"Alix Didier Fils-Aimé states that Haiti has established specialized judicial hubs and new criminal codes to combat impunity and modernize its legal system, though he notes these measures are insufficient without arresting those terrorizing the population.","Haiti disarmament":"Alix Didier Fils-Aimé states that Haiti has reactivated its national commission for disarmament and launched a peace dividend fund, emphasizing that security and development must progress together to provide alternatives to violent actors.","Haiti trade":"Alix Didier Fils-Aimé expresses gratitude for the US extension of trade preferences and calls for their further extension, while urging other nations to implement similar mechanisms.","Haiti aid":"Alix Didier Fils-Aimé calls for shifting Haiti's approach from receiving aid to fostering investment and production.","Haiti elections":"Alix Didier Fils-Aimé states that the government's major commitment is to give the Haitian people a voice through elections to break the cycle of political instability.","Haiti France relations":"Alix Didier Fils-Aimé welcomes the work of the mixed commission and expresses eagerness for its report while outlining a commitment to restoring peace and security in Haiti.","Haiti development":"Alix Didier Fils-Aimé states that Haiti's security and development will be rooted in national institutions, shifting from aid to investment and from dependency to partnership."},"claims":[{"t":68,"quote":"More than 80 years ago, in the wake of a war that plunged the world into chaos, Haiti, a founding member of the United Nations, joined the nations of the world to make a pledge for peace, for dialogue, and respect for human dignity.","topic":"Haiti crisis","kind":"fact"},{"t":90,"quote":"while deadly crises and conflicts have and the climate emergency is intensifying and new divisions are threatening stability in Haiti and throughout the world, this founding endeavor is being put to the test.","topic":"Haiti crisis","kind":"fact"},{"t":149,"quote":"I still remember fondly his visit to Porto France on the 16th of June, 2026, which bore witness to his solidarity toward the Haitian people.","topic":"UNGA","kind":"fact"},{"t":198,"quote":"Kindred peoples who by contributing to the gang suppression force and supporting its full roll out roll out have chosen to share with us the burden of fighting for peace","topic":"Haiti security","kind":"fact"},{"t":236,"quote":"in the modernization of our national security the opening of the Dominican Republic to dialogue and and its advocacy for a sustainable resolution to the Haitian crisis","topic":"Haiti security","kind":"fact"},{"t":283,"quote":"Breaking the chains of slavery and bringing to life on a land conquered by sacrifice, blood, and sweat the first free black republic of the world.","topic":"Haiti history","kind":"fact"},{"t":296,"quote":"This epic story is the eternal proof that no empire can be more powerful than the thirst for freedom of a people.","topic":"Haiti history","kind":"fact"},{"t":347,"quote":"In overthrowing me, you have done no more than cut down the trunk of the tree of liberty and St. Doming. It will spring back from the roots, for they are numerous and deep.","topic":"Haiti liberty","kind":"fact"},{"t":364,"quote":"the tree did grow back. It got larger and it has gone through the centuries and is continuing.","topic":"Haiti liberty","kind":"fact"},{"t":446,"quote":"This is a deep injustice.","topic":"Haiti climate","kind":"fact"},{"t":450,"quote":"The fact that those who historically contributed the least are among those who are paying the heaviest price","topic":"Climate finance","kind":"fact"},{"t":471,"quote":"No people must have to choose between responding to an emergency and financing its development","topic":"Climate finance","kind":"fact"},{"t":551,"quote":"For settled abroad have contributed to the societies that welcomed them.","topic":"Haiti migration","kind":"fact"},{"t":572,"quote":"Haiti was a land of welcome, refuge, and hope.","topic":"Haiti migration","kind":"fact"},{"t":648,"quote":"That is the case with the security crisis in Haiti with which led to the exodus of thousands of Haitians.","topic":"Haiti migration","kind":"fact"},{"t":656,"quote":"The response to this crisis in Haiti will mean reestablishing security, stability, and economic recovery. These are the three priorities of my government.","topic":"Haiti crisis","kind":"fact"},{"t":683,"quote":"At a time when the United Nations must produce tangible results for everyone, Haiti can become a model of success of international cooperation.","topic":"Haiti crisis","kind":"fact"},{"t":731,"quote":"Massacres, berved families, women that have fallen victim to despicable violence, children deprived of their innocence, and communities chased away from their homes need to compel us to act.","topic":"Haiti violence","kind":"fact"},{"t":762,"quote":"Through their courage, they have written with their blood as ink a page in the book of our struggle for security and peace.","topic":"Haiti violence","kind":"self_credit"},{"t":782,"quote":"for these 12 million women, men and children.","topic":"Haiti violence","kind":"number"},{"t":829,"quote":"Through the P4000 program, we are continuing to train 4,000 police officers. Over 2,000 have already been trained, and a new core cohort is set to graduate from the police academy next November.","topic":"Haiti security","kind":"number"},{"t":842,"quote":"In parallel with this, over 1,500 new soldiers have already been trained.","topic":"Haiti security","kind":"number"},{"t":847,"quote":"we are putting in place a program aiming to train 15,000 new soldiers over the next 3 years.","topic":"Haiti security","kind":"number"},{"t":892,"quote":"still hasn't reached on the ground the planned force of 5,500 members.","topic":"Haiti security","kind":"number"},{"t":948,"quote":"These are weapons that are killing Haitians that are sowing terror in our neighborhoods and cutting down innocent lives.","topic":"Haiti security","kind":"fact"},{"t":954,"quote":"And they're not being produced in Haiti. They are arriving here through transnational criminal networks that are fueling insecurity and strengthening the capacity of gangs to act while threatening stability of our entire region.","topic":"Haiti security","kind":"fact"},{"t":1007,"quote":"This is why we have established two specialized judicial hubs to strengthen the struggle against impunity, financial crimes, mass crimes, and sexual","topic":"Haiti justice","kind":"fact"},{"t":1021,"quote":"The 1st of January 2027 saw the entry into force of our new criminal codes and codes of code of criminal procedure.","topic":"Haiti justice","kind":"number"},{"t":1048,"quote":"we've reactivated our national commission for disarmament, demobilization, and reintegration. And we've launched the peace dividend fund in Haiti.","topic":"Haiti disarmament","kind":"fact"},{"t":1106,"quote":"We call upon security in and of itself to bear the burden of peace. Economic recovery needs to be the other pillar.","topic":"Haiti trade","kind":"fact"},{"t":1116,"quote":"This is why we welcome the decision taken by the administration of President Donald Trump to extend through 2028 the trade preference known as hope help.","topic":"Haiti trade","kind":"fact"},{"t":1168,"quote":"This is why today Haiti is calling for a paradigm shift. We need to move from aid to investment, from assistance to production, from dependency to partnership.","topic":"Haiti aid","kind":"fact"},{"t":1289,"quote":"I belong to a generation that knew the dictatorship that placed so much hope in democracy after 1987, but too often saw these hopes collide with political instability and recurrent","topic":"Haiti elections","kind":"fact"},{"t":1341,"quote":"Today the required resources have been mobilized. The C enrollment centers are open. Citizens are registering.","topic":"Haiti elections","kind":"fact"},{"t":1351,"quote":"Political parties and groups have been accredited and candidates are undertaking the formalities needed for them to participate in the elections.","topic":"Haiti elections","kind":"fact"},{"t":1383,"quote":"violence, criminal networks, illicit financing, and those that are supporting them must find no path to access the ballot box.","topic":"Haiti elections","kind":"fact"},{"t":1430,"quote":"Its roots run through centuries of injustice, through the debt of and the debt of independence remains the heaviest burden to bear.","topic":"Haiti elections","kind":"fact"},{"t":1444,"quote":"This is why we welcome the work of the mixed commission of Haitian and French historians and we are very eagerly awaiting the publication of its report.","topic":"Haiti France relations","kind":"fact"},{"t":1502,"quote":"More than two centuries ago, Haiti told the world that a people can cast off its chains.","topic":"Haiti France relations","kind":"fact"},{"t":1523,"quote":"Our security will be rooted in the long term on our own institutions and our development will move from aid to investment, from dependency to partnership, from emergency to","topic":"Haiti development","kind":"fact"}],"promises":[{"t":576,"quote":"And we are working to make sure it becomes that again.","topic":"Haiti migration","kind":"promise"},{"t":1284,"quote":"give the Haitian people a voice through elections","topic":"Haiti elections","kind":"promise"},{"t":1312,"quote":"this transition needs to come to an end","topic":"Haiti elections","kind":"promise"},{"t":1474,"quote":"We will bring security back to our communities.","topic":"Haiti France relations","kind":"promise"},{"t":1478,"quote":"We will give our people a voice again.","topic":"Haiti France relations","kind":"promise"},{"t":1481,"quote":"And we will return hope to our young people.","topic":"Haiti France relations","kind":"promise"},{"t":1493,"quote":"We will prove to them tomorrow that peace can be built, can be defended, and can triumph over fatalism.","topic":"Haiti France relations","kind":"promise"},{"t":1560,"quote":"It is our promise to our children. It is our rendevous with history.","topic":"Haiti development","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":null,"text":"On behalf of the assembly, I wish to thank the prime minister of the Commonwealth of the Bahama. The assembly will hear an address by His Excellency Alex DDA Fizz, Prime Minister of the Republic of Heighti. I request I request protocol to escort his excellency and invite him to address the The last &gt;&gt; President of the General Assembly, Secretary General, heads of state and government, permanent representatives, distinguished delegates, Haitian people. And taking the floor at this general assembly, I feel the weight of history."},{"t":68,"topic":"Haiti crisis","text":"More than 80 years ago, in the wake of a war that plunged the world into chaos, Haiti, a founding member of the United Nations, joined the nations of the world to make a pledge for peace, for dialogue, and respect for human dignity. while deadly crises and conflicts have and the climate emergency is intensifying and new divisions are threatening stability in Haiti and throughout the world, this founding endeavor is being put to the test. It is imperative that given the crisis that Haiti is grappling with and given those that are causing so much upheaval throughout the world, it is imperative for nations to close ranks around what is essential that is peace, security, and the well-being of all peoples."},{"t":129,"topic":"UNGA","text":"This is the whole point of the topic that brings us together this year. Mr. President, we cong I I congratulate you on your election as president of the general assembly. I also wish to hail the secretary general, Mr. Antonio Gutes, for his unwavering commitment to peace. I still remember fondly his visit to Porto France on the 16th of June, 2026, which bore witness to his solidarity toward the Haitian people. In these difficult times that our country is undergoing, Haiti wishes to extend its gratitude to all of its partners and friends that have continued to stand by its side. In this regard, I would like to hail the commitment of the United Nations system and especially the commitment of the security council and that of the Organization of American States, KARACKOM and the European Union whose support remains essential more than ever."},{"t":195,"topic":"Haiti security","text":"I want to pay a particular tribute to the Kindred peoples who by contributing to the gang suppression force and supporting its full roll out roll out have chosen to share with us the burden of fighting for peace and Haiti will never forget their solidarity nor their sacrifices. I also want to underscore the privileged partnership with the United States of America and the steadfast support of Canada and the invaluable assistance of our partners such as France, Chile, and Mexico in the modernization of our national security the opening of the Dominican Republic to dialogue and and its advocacy for a sustainable resolution to the Haitian crisis. I express my gratitude for that."},{"t":256,"topic":"Haiti history","text":"Finally, we wish to recognize the integrated office in Haiti, the funds and programs present on the ground, as well as all of our multilateral partners. We thank them all for their staunch commitment side by side with the Haitian people. President, before this Augusta assembly, I am bringing to you the voice of a people that has etched its name in the annals of history by daring to do what was unthinkable. Breaking the chains of slavery and bringing to life on a land conquered by sacrifice, blood, and sweat the first free black republic of the world. This epic story is the eternal proof that no empire can be more powerful than the thirst for freedom of a people. How can we forget the destiny and the hidden tears of Tuson Luvur torn violently away from his the land of his birth."},{"t":319,"topic":"Haiti liberty","text":"cast into icy solitude and a dungeon in ford dejour made to suffer hardship and humiliation. The this all brought down Tusant Luvverur but his fight for freedom remained alive through Desoline Kristoff Pat and all of our other founding fathers and mothers. Tusant Luvur predicted it. He said, \"In overthrowing me, you have done no more than cut down the trunk of the tree of liberty and St. Doming. It will spring back from the roots, for they are numerous and deep. the tree did grow back. It got larger and it has gone through the centuries and is continuing. And even though today criminal violence is threatening its roots and trying to strip our children of the fruits of this liberty so dearly one, Haiti will resist."},{"t":382,"topic":"Haiti climate","text":"Haiti is standing tall. It is standing tall because the peoples born in light have never given in to the forces of chaos. Haiti is standing tall because the people born of sacrifice know the price of liberty, peace, and security. Haiti knows because it felt it in its own flesh that these gains are never definitively won and that when they are under threat, one must have the courage to defend them. This is the struggle that Haiti is undergoing today. And that's why we call upon the world not to save it, but to stand side by side with it while it takes its own destiny into its own hands. Mr. President, I am bringing to you the voice of Haiti, but also the voice of those peoples who our world too often asks to bear the weight of crises that they did not create. For small states such as Haiti, the cost of climate change has become This is a deep injustice."},{"t":450,"topic":"Climate finance","text":"The fact that those who historically contributed the least are among those who are paying the heaviest price, often to the detriment of their own devoted to adaptation and resilience need to be commen commensurate with these challenges. No people must have to choose between responding to an emergency and financing its development. Access to capital, to markets, and to technologies need to be more fair. Our international financial architecture must evolve to better respond to the needs and the realities of the most vulnerable countries. Artificial intelligence offers up colossal opportunities, but without regulations or ethical guard rails, it risks deepening existing rifts. Technology must remain a tool for shared progress and it must serve humanity. We need to be the masters of technology and never its subjects and no people should ever be left behind."},{"t":518,"topic":"Haiti migration","text":"We also need to keep the promise of a world where no one is condemned to suffer hunger, to be deprived of care, or to be displaced by war or to fall victim to exclusion or discrimination. This same requirement to uh for dignity needs to guide our approach to migrations as well because behind statistics and debates there are women, children and men who carry with them a history, talents, hopes and sometimes the burden of exile. For settled abroad have contributed to the societies that welcomed them. From this rostrm, I wish to express my thanks to the countries that have opened their doors and have encouraged their integration. Haiti was a land of welcome, refuge, and hope. And we are working to make sure it becomes that again. We want it to be a country where one can rest there, return, and live and build one's future and dignity."},{"t":588,"topic":"Haiti migration","text":"But I also want to recall forcefully that respect for dignity and fundamental rights of all migrants must be upheld no matter their situation. No circumstance can justify trampling their dignity underfoot. The protection of a border and respect for human dignity are not incompatible. These must go hand in hand. A border can and must be protected without sacrificing human dignity. The destiny of migrants. The destiny of migrants calls upon us to shoulder ass shared responsibility and uh ensure sustainable responses because crises that are left to fester will breed displacement and forced migration. That is the case with the security crisis in Haiti with which led to the exodus of thousands of Haitians."},{"t":656,"topic":"Haiti crisis","text":"The response to this crisis in Haiti will mean reestablishing security, stability, and economic recovery. These are the three priorities of my government. Mr. President, the Republic of Haiti remains deeply committed to multilateralism and to the capacity of nations to unite their forces when urgent situations call for them to do so. At a time when the United Nations must produce tangible results for everyone, Haiti can become a model of success of international cooperation. It can be the proof of what we can accomplish together with respect for the will of nations and uh around a vision conveyed by the countries themselves because no matter how complex it may be the Haitian crisis is not insurmountable. We are at a watershed moment."},{"t":718,"topic":"Haiti violence","text":"The the time is not a time for any half measures or partially honored commitments or too a too tepid response given the scale of the threat. Massacres, berved families, women that have fallen victim to despicable violence, children deprived of their innocence, and communities chased away from their homes need to compel us to act. And uh here I want to pay tribute to all of the victims of this violence. Their loss compels us to ensure that justice is done. I want to pay tribute as well to the police officers and the soldiers, Haitians, Kenyans, and the residents of other nations who fell while serving Haiti. Through their courage, they have written with their blood as ink a page in the book of our struggle for security and peace. Haiti will never forget their sacrifice for them, for their families, for these 12 million women, men and children."},{"t":786,"topic":"Haiti security","text":"For children that are asking only to grow up, to dream, and to live in peace. We cannot resign ourselves to seeing deaths and wounded people be mere numbers in our reports. We need to act because in Haiti today, one more victim is too many victims and Haiti is already acting. We've taken we made the choice to strengthen the operational capacity of our national security forces because the security of Haiti must ultimately be based on the capacity of the Haitian state. We are recruiting. We are training. And we are becoming stronger. Through the P4000 program, we are continuing to train 4,000 police officers. Over 2,000 have already been trained, and a new core cohort is set to graduate from the police academy next November. In parallel with this, over 1,500 new soldiers have already been trained."},{"t":847,"topic":"Haiti security","text":"and we are putting in place a program aiming to train 15,000 new soldiers over the next 3 years. What's more, we've stepped up our budget to invest in our two security forces. Our goal is not only to respond to the crisis of today. It is to build capacity that will allow Haiti to ensure itself fully and sustainably its own security. It is regrettable that the force that was supposed to temporarily support these efforts uh that this force is not yet fully operational and still hasn't reached on the ground the planned force of 5,500 members. That is why from this rostrm we emphasize the need to renew the mandate of the gang suppression force and we want to see its full implementation with the forces the equipment and the resources that are needed for it to discharge its mission."},{"t":919,"topic":"Haiti security","text":"The experience from the multinational security support mission should serve as a lesson. A mandate is not enough. There's a need for forces. Equipment is needed and one needs to resolve to see the effort through. However, there is another security challenge that should compel us all collectively to act. The illicit trafficking in weapons and These are weapons that are killing Haitians that are sowing terror in our neighborhoods and cutting down innocent lives. And they're not being produced in Haiti. They are arriving here through transnational criminal networks that are fueling insecurity and strengthening the capacity of gangs to act while threatening stability of our entire region. For as long as this traffic prospers, violence will find ways to perpetuate. Dismantling this traffic is a shared responsibility."},{"t":981,"topic":"Haiti justice","text":"We therefore need to move beyond advocating for Haiti. The security of our island also requires effective border control. Mr. President, impunity is the other face of insecurity. We need to combat it with the same resolve. This is why we have established two specialized judicial hubs to strengthen the struggle against impunity, financial crimes, mass crimes, and sexual The 1st of January 2027 saw the entry into force of our new criminal codes and codes of code of criminal procedure. And in so doing, Haiti will pass an historic milestone in the modernization of its But uh because it's not enough to arrest those who are terrorizing the population."},{"t":1044,"topic":"Haiti disarmament","text":"They need to be judged and justice needs to be done. At the same time, we've reactivated our national commission for disarmament, demobilization, and reintegration. And we've launched the peace dividend fund in Haiti. and I invite all of our partners to support it. It is imperative to take away from violent actors their capacity to recruit by offering our young people credible alternatives and genuine opportunities. For this, security and development must come together and must progress Neither one can be sustainable without the other. Mr. President emergency aid has saved lives. Haiti is grateful for that. However, the long-term well-being of a people cannot remain indefinitely dependent on aid and on charity."},{"t":1106,"topic":"Haiti trade","text":"We call upon security in and of itself to bear the burden of peace. Economic recovery needs to be the other pillar. This is why we welcome the decision taken by the administration of President Donald Trump to extend through 2028 the trade preference known as hope help. We are deeply grateful for this gesture of friendship which is an important step for our economic recovery and we call for it to be extended uh by 10 years. We also want to extend our gratitude to the United Kingdom for the developing count's trading scheme and we call upon more countries to put in place similar mechanisms that are capable of transforming access to markets into opportunities for trade and Haiti needs investment to craft its future."},{"t":1168,"topic":"Haiti aid","text":"This is why today Haiti is calling for a paradigm shift. We need to move from aid to investment, from assistance to production, from dependency to partnership. And we must gradually transform resources mobilized in order to manage the crisis into investments that can create jobs and sustainable opportunities in particular for our young people and our women. Because when you no longer hear the sound of the guns, you need to hear the sounds of peace. engines that are starting, construction sites that are beginning work. Again, bustling markets, women that are running businesses, young people that are working, the laughter of children that are playing, and our streets that again are rediscovering the rhythm of our music and our life."},{"t":1234,"topic":"Haiti elections","text":"Those who have had the privilege of knowing Haiti know that this country exists behind the images of There's a people that it's that is welcoming and hospitable, a vibrant culture with unique knowledge with stunning beaches and heritage and exceptional rich richness. We need to recreate the conditions so that the world can come to Haiti again to discover it, invest in it, do business there, and stay there and come back. This is what peace will look like, the peace we want and that we must build. President, the security for which the international community must remain fully mobilized side by side with us should also allow us to honor the second major commitment of the government which I lead and that is give the Haitian people a voice through elections. I'm I I belong to a generation that knew the dictatorship that placed so much hope in democracy after 1987, but too often saw these hopes collide with political instability and recurrent In order to break this cycle, I agreed to serve my country with the conviction that this transition needs to come to an end."},{"t":1316,"topic":"Haiti elections","text":"It needs to come to an end through the ballot box and through the ballot. This is why we have committed to the electoral process with respect for the national pact for stability and for the organization of elections which is the fruit of a broad consensus among the political class. Today the required resources have been mobilized. The C enrollment centers are open. Citizens are registering. Political parties and groups have been accredited and candidates are undertaking the formalities needed for them to participate in the elections. We want free, credible, inclusive and honest elections. The participation of women is encouraged and young people are called upon to take their full place in that election as voters, candidates, and stakeholders for our democracy."},{"t":1379,"topic":"Haiti elections","text":"Furthermore, measures have been taken to preserve the integrity of the process. violence, criminal networks, illicit financing, and those that are supporting them must find no path to access the ballot box. it's not just the next government that's at stake in these elections. It is the future of Haiti. And this future bears the face of our Mr. President, the Haitian crisis is also one of the most painful expressions of the divides of our age. This chaos is no accident of history. Its roots run through centuries of injustice, through the debt of and the debt of independence remains the heaviest burden to bear."},{"t":1444,"topic":"Haiti France relations","text":"This is why we welcome the work of the mixed commission of Haitian and French historians and we are very eagerly awaiting the publication of its report. Mr. President, yesterday our ancestors won their freedom from the shadows of servitude. Today our generation will win peace from the shadows of violence. We will bring security back to our communities. We will give our people a voice again. And we will return hope to our young people. The challenges are colossal, but our willpower is even greater. We've proven to the world that freedom was possible. We will prove to them tomorrow that peace can be built, can be defended, and can triumph over fatalism. More than two centuries ago, Haiti told the world that a people can cast off its chains."},{"t":1509,"topic":"Haiti development","text":"Today from this high rostrm, Haiti is telling the world that a people Haiti is telling the world that a people can also break the cycle of violence, of transition and of dependency. Our security will be rooted in the long term on our own institutions and our development will move from aid to investment, from dependency to partnership, from emergency to The tree of liberty that Tusant spoke of still stands tall and our generation now needs to let it bear the fruit of peace. This is our responsibility. It is our duty. It is our promise to our children. It is our rendevous with history. May God bless the Republic of Haiti and may God bless the world."},{"t":1570,"topic":null,"text":"Thank you. On behalf of the assembly, I wish to thank the prime minister of the Republic of Hayi."}],"compare":[{"topic":"Haiti","share":0.2118,"mean":0.0054,"rank":2,"others":11},{"topic":"Climate Change","share":0.0455,"mean":0.0428,"rank":74,"others":77},{"topic":"UN & its reform","share":0.0441,"mean":0.2056,"rank":170,"others":170}]};
